'use strict';
window.SadhanaReportDocument=({start,end,length,sections})=>`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sadhana report ${start} to ${end}</title><style>
@page{size:A4 portrait;margin:14mm 12mm}*{box-sizing:border-box}body{font:13px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#293e36;margin:0;background:#edece5}.actions{padding:16px 24px;background:#fff;border-bottom:1px solid #dce2da;position:sticky;top:0;display:flex;gap:16px;align-items:center;flex-wrap:wrap;z-index:1}.actions button{background:#285d4c;color:#fff;border:0;padding:12px 18px;border-radius:6px;font:inherit;cursor:pointer}.actions p{margin:0;font-size:12px;color:#52665a}main{max-width:900px;margin:24px auto;background:#fffef9;padding:42px}.report-header{position:relative;text-align:center;padding:30px 20px 32px;border-top:3px solid #b78b45;border-bottom:1px solid #d9c9a6;background:#f6f1e4}.ornament{font:32px Georgia,serif;color:#9c7539;line-height:1;margin-bottom:16px}.eyebrow{font-size:10px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:#7a683f}h1{font:46px/1.13 Georgia,serif;margin:12px 0;color:#234b3b}.dates{display:inline-block;border-top:1px solid #d9c9a6;padding-top:14px;margin:0;font-size:13px;font-weight:600}.period-length{font-weight:400;color:#736a53}.section-heading{padding:0 0 16px}section{margin-top:30px}h2{font:30px/1.2 Georgia,serif;margin:5px 0 8px}section p{font:italic 15px Georgia,serif;color:#6c745f;margin:0}table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:12px}th,td{text-align:left;padding:10px 8px;border-bottom:1px solid #e8e8de;overflow-wrap:anywhere;vertical-align:top}th{background:#f0f2ea;color:#5e6b60;font-size:9px;letter-spacing:.7px;text-transform:uppercase;font-weight:600}th:first-child{width:7%}th:nth-child(2){width:34%}th:nth-child(3){width:23%}.overall-table th:nth-child(2){width:48%}.overall-table th:nth-child(3){width:23%}.result{font-weight:650;font-variant-numeric:tabular-nums}thead{display:table-header-group}tr{break-inside:avoid}td:first-child{color:#7a8377;font-size:10px}.score-group{--tone:#52665a;--wash:#edf0eb;margin:0 0 24px;border-top:2px solid var(--tone)}.group-heading{display:flex;gap:10px;align-items:baseline;justify-content:space-between;background:var(--wash);padding:12px 14px;break-after:avoid;color:var(--tone)}h3{font:24px/1.2 Georgia,serif;margin:0}.group-heading span{font-size:10px;white-space:nowrap}.score-group th{background:var(--wash)}.score-own{--tone:#873d4a;--wash:#f8e9ec}.score-bhrose{--tone:#925622;--wash:#faeddd}.score-mercy{--tone:#806519;--wash:#f9f3d8}.score-good{--tone:#2b6248;--wash:#e6f0e6}.score-group .result{color:var(--tone)}.section-heading{break-after:avoid}footer{margin-top:30px;border-top:1px solid #d9c9a6;padding-top:18px;font-size:10px;color:#6c745f;break-inside:avoid}.report-contact{margin:16px 0 0}.report-contact a{color:#476149;text-underline-offset:3px}.closing{font:italic 18px Georgia,serif;color:#476149;margin:0 0 12px}.report-header,.group-heading,th,.score-group{print-color-adjust:exact;-webkit-print-color-adjust:exact}@media(max-width:600px){main{padding:18px;margin:12px}.report-header{padding:24px 12px}h1{font-size:36px}h3{font-size:21px}.group-heading{align-items:flex-start;flex-direction:column;gap:5px}table{font-size:11px}th,td{padding:8px 5px}}@media print{body{background:white}main{padding:0;margin:0;max-width:none;background:white}.actions{display:none}section+section{break-before:page}a{color:inherit}}
</style></head><body><div class="actions"><button id="printReport" type="button">Print / Save as PDF</button><p>Select “Save as PDF” as the destination in your browser’s print window.</p></div><main><header class="report-header"><div class="ornament" aria-hidden="true">✦</div><p class="greeting">Hare Krishna</p><p class="dedication">All glories to Srila Prabhupada.</p><span class="eyebrow">Our sadhana journey</span><h1>Growing in sadhana</h1><p class="dates">${fmtDate(start)} – ${fmtDate(end)} <span class="period-length"> · ${length} days</span></p></header>${sections.join('')}<footer><p class="closing">May we encourage one another to keep growing.</p><p>Results cover every day in the dates above; lowest scores appear first. Scores reflect reported practice, not the whole of a person’s spiritual life. Missing reports and invalidated duplicate days earn no credit; unreadable components earn no credit. Unresolved personal targets remain unranked.</p><p class="report-contact"><a href="mailto:dixit.yashsvi@gmail.com?subject=Sadhana%20dashboard%20feedback">Feedback / Contact developer</a></p></footer></main></body></html>`;
